INSERT INTO public.question_bank_translations (question_id, locale, question_text, options, explanation)
VALUES ('8cc81ee6-d421-57af-8676-382f82291738', 'uz', '«Geografiya fanining mazmuni va tadqiqot usullari» mavzusida xarita qatlami yordamida «geografiya»ga oid xulosa chiqarish kerak. Qaysi yondashuv eng asosli? (Mashq M1-D1-1)', '[{"text": "O\u2018lchov birligini e\u2019tiborsiz qoldirish"}, {"text": "Biror dalil tekshirmay taxminni fakt deyish"}, {"text": "Birlik, manba va sabab\u2013oqibatni tekshirib, dalil bilan xulosa chiqarish"}, {"text": "Faqat nomga qarab xulosa chiqarish"}]'::jsonb, 'geografiya haqidagi fikr tekshiriladigan manbaga tayanishi zarur; xarita qatlamidagi ma’lumotni solishtiring.')
