INSERT INTO public.question_keys (question_id, key)
VALUES ('8cc81ee6-d421-57af-8676-382f82291738', '{"correct_code": "C", "correct_index": 2, "correct_text": "Birlik, manba va sabab\u2013oqibatni tekshirib, dalil bilan xulosa chiqarish", "rationale": "geografiya haqidagi fikr tekshiriladigan manbaga tayanishi zarur; xarita qatlamidagi ma\u2019lumotni solishtiring.", "wrong_explanations": {"A": "\u00abO\u2018lchov birligini e\u2019tiborsiz qoldirish\u00bb \u2014 bu savol shartiga mos kelmaydi: geografiya haqidagi fikr tekshiriladigan manbaga tayanishi zarur; xarita qatlamidagi ma\u2019lumotni solishtiring. Xato talqin: muhim sabab, mezon yoki birlik noto\u2018g\u2018ri tanlangan.", "B": "\u00abBiror dalil tekshirmay taxminni fakt deyish\u00bb \u2014 bu savol shartiga mos kelmaydi: geografiya haqidagi fikr tekshiriladigan manbaga tayanishi zarur; xarita qatlamidagi ma\u2019lumotni solishtiring. Xato talqin: muhim sabab, mezon yoki birlik noto\u2018g\u2018ri tanlangan.", "D": "\u00abFaqat nomga qarab xulosa chiqarish\u00bb \u2014 bu savol shartiga mos kelmaydi: geografiya haqidagi fikr tekshiriladigan manbaga tayanishi zarur; xarita qatlamidagi ma\u2019lumotni solishtiring. Xato talqin: muhim sabab, mezon yoki birlik noto\u2018g\u2018ri tanlangan."}}'::jsonb)
